with d as (select value r from jsonb_array_elements($q$[{"notes":["Soak wooden skewers in water for 30 minutes before threading if using them instead of metal ones.","Make the suya spice ahead and store in an airtight container for up to two weeks.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Thread the beef cubes onto skewers, packing them tightly together. Rub with oil, salt, black pepper and ground ginger."},{"text":"Pulse the roasted peanuts in a food processor until they're finely ground but still have some texture, not a smooth butter. Tip into a shallow bowl and stir through the cayenne, paprika, ground ginger, salt, black pepper and garlic."},{"text":"Heat a griddle, grill or large frying pan over high heat until very hot. Working in batches, sear the skewers for 3 to 4 minutes, turning to cook all sides until the beef is deeply browned and cooked through (the meat should reach 75°C inside)."},{"text":"Immediately after cooking, while still hot, roll each skewer in the suya spice mixture until generously coated on all sides."},{"text":"Serve hot, straight away."}],"id":"e2c7f28f-8f02-4b35-8926-daad7f65fde3"},{"notes":["A potjie needs at least 45 minutes on low, steady heat. If your braai is too hot, move the pot to the edge and add less frequent wood.","You can prep all the veg at home and bring it in containers to the braai for faster assembly.","Leftover potjiekos reheats beautifully the next day.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Place a 7-litre cast iron potjie (or large heavy-based pot) over medium coals on the braai. Heat the oil until shimmering, then add the beef in batches. Brown on all sides, about 8 minutes per batch, then remove and set aside."},{"text":"Reduce the heat to low coals (move the pot away from the hottest part of the braai). Add the onion to the pot and cook, stirring, for 3 minutes until slightly softened."},{"text":"Add the browned beef back to the pot, then layer in the carrots and potatoes. Sprinkle with garlic and thyme, then season with salt and pepper."},{"text":"Pour the beef stock over everything. Cover with the lid and let it cook on low heat for about 1 hour, until the potatoes and beef are almost tender. Resist lifting the lid too often, you want to keep the heat in."},{"text":"Add the cabbage wedges, nestling them into the liquid. Replace the lid and cook for another 20 minutes until the cabbage is tender and the beef is cooked through."},{"text":"Taste and adjust the seasoning. Serve straight from the pot, family-style, with crusty bread to soak up the liquid."}],"id":"ae27383a-1e21-43db-9d18-76006c448d7c"},{"notes":["Make the macaroni salad ahead: it's even better the next day.","If you can't find mirin, use 2 tbsp honey instead.","Leftover chicken keeps for three days in the fridge; reheat gently with a splash of water.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Cook the macaroni according to packet directions until al dente, then drain and rinse under cold water. In a bowl, mix the mayonnaise, rice vinegar, sugar, carrot, and onion. Toss the cooled pasta through. Season to taste with salt and pepper. Chill while you cook the chicken."},{"text":"In a small bowl, whisk together the soy sauce, brown sugar, mirin, garlic, and ginger. Set aside."},{"text":"Heat the oil in a large frying pan over medium-high heat. Season the chicken thighs with salt and pepper on both sides. Place skin-side down in the pan and cook for 6–7 minutes until the skin is golden and crispy."},{"text":"Turn the thighs skin-side up and cook for another 4–5 minutes until cooked through (internal temperature 75°C). Pour off most of the fat from the pan, leaving about 1 tbsp."},{"text":"Pour the teriyaki sauce over the chicken. Mix the cornflour with the water until smooth, add to the pan, and stir gently. Simmer for 2–3 minutes, stirring occasionally, until the sauce thickens and coats the chicken."},{"text":"Divide the rice between four plates, making two scoops per plate. Top with the glazed chicken thighs and any sauce. Serve the macaroni salad on the side and garnish with spring onion if you like."}],"id":"67eb5369-b9f4-4c2c-9247-f057a11adec1"},{"notes":["Perkedel is best served warm. You can make the fritters ahead and reheat them in a moderate oven (180°C) for 8 minutes.","Let the boiled potato cool completely, warm potato breaks down when you fry it and won't stay soft inside.","Serve with sambal or sweet soy sauce for dipping.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"c0013384-f85d-4c13-a55d-db259e428915"},{"diets":["vegetarian","vegan","no-gluten","no-dairy"],"id":"df1aad68-b793-4a1d-995e-ae3ba8771a26"},{"notes":["This keeps in the fridge for 3 days and tastes better the next day as the flavours deepen. Serve it cold as banchan or gently reheat.","You can use any dried chillies you have, guajillo or ancho work well too, though the flavour will shift. Stay with long varieties if you can; they soften into beautiful strands."],"id":"dfb1aa42-b9ad-4b0e-b149-93068436e0dd"},{"notes":["Lugaw keeps in the fridge for 2 days; reheat gently with a little extra stock to loosen it.","Add crispy fried garlic and egg just before serving so the garlic stays crunchy.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"steps":[{"text":"Bring the chicken stock to a boil in a large pot until bubbling steadily. Add the rice and salt, stir well, and return to a boil."},{"text":"Reduce heat to low, cover partly, and simmer, stirring often, for 40 minutes. The rice should break down and the porridge should be creamy and thick."},{"text":"While the lugaw cooks, boil the eggs in a separate pot for 10 minutes until hard-boiled. Cool, shell, and halve them."},{"text":"Heat the neutral oil in a small frying pan over medium-high heat. Add the sliced garlic and fry, stirring, until golden and crispy, about 3 minutes. Drain on paper towel."},{"text":"Divide the lugaw among serving bowls. Top each with a halved egg, crispy fried garlic, and spring onion if using. Serve warm."}],"id":"fb592060-489a-4c14-8126-23f541d56f8d"},{"notes":["Make ahead: prepare the parcel up to 4 hours before roasting.","The cooking liquid makes a silky pan sauce, don't skip it. Serve with horta (simply boiled greens) or crusty bread to mop it up.","Leftovers shred beautifully and work in pies or as a filling for spanakopita.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Pat the lamb dry and season generously inside and out with salt and pepper."},{"text":"Tear off a sheet of baking paper about 1 m long. Place the lamb in the centre and scatter the onion, garlic, tomatoes, feta and oregano around and over it."},{"text":"Drizzle with olive oil, then fold the paper up and over the lamb, folding and creasing the edges to seal it completely, the parcel should be airtight."},{"text":"Place the parcel on a large roasting tray and roast at 160°C for 4 to 5 hours. The lamb is done when a fork slides through the meat like butter."},{"text":"Carefully open the paper (steam will billow out). Transfer the lamb to a serving platter and let it rest for 10 minutes while you pour the cooking liquid into a small saucepan."},{"text":"Skim the fat from the surface of the liquid and warm it gently over medium heat. Season with salt, pepper and lemon juice to taste, then pour over the lamb and serve."}],"id":"dd60d5e7-974c-4014-90be-96eb5f82d2c0"},{"notes":["The coconut bread keeps wrapped for two days. Taro and pisupo are best made the day of, but can be reheated gently.","Scale up easily for bigger gatherings: add another tin of pisupo and kg of taro for every five extra people.","Let everyone build their own plate, the mains are flexible, and plenty of fruit rounds it out for those with lighter appetites.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Start the taro: bring a large pot of salted water to the boil. Add taro chunks and simmer for 25–30 minutes until tender and cooked through. Drain well and place in a serving bowl. Keep warm."},{"text":"While the taro cooks, heat oil in a large frying pan over medium heat. Add onions and cook, stirring, until soft and golden, about 8 minutes. Add corned beef, breaking it up with a wooden spoon, and stir-fry for 5–8 minutes until warmed through. Season with salt and pepper. Transfer to a serving platter."},{"text":"Make the coconut bread: preheat oven to 180°C. Sift flour, baking powder and salt into a large bowl. In another bowl, whisk together sugar, coconut milk, desiccated coconut, eggs, oil and vanilla. Pour wet ingredients into dry ingredients and stir until just combined, don't overmix."},{"text":"Divide batter between two greased 20 cm loaf tins and bake for 35–40 minutes until a skewer inserted in the centre comes out clean. Cool in tins for 5 minutes, then turn out onto a wire rack. Slice and arrange on a platter."},{"text":"Arrange all fruit on platters, keeping different types separate so people can choose."},{"text":"Set the table with pisupo, taro, coconut bread and fruit platters. Serve family-style, with everyone helping themselves."}],"id":"ad0b7c84-dd25-4930-80d0-e06496efaa96"},{"notes":["Make the sausages up to a day ahead and refrigerate on a tray before grilling.","Pork sausage casings are in the meat section at good butchers and some larger supermarkets. Soak them in water for 30 minutes before filling so they're easier to work with.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Mix the pork mince with coriander, garlic chives, spring onion, chilli, fish sauce, ground cumin and ground coriander in a bowl until just combined."},{"text":"Fit a sausage casing onto a sausage stuffer or piping bag fitted with a large plain nozzle. Pipe the filling into the casing, pushing gently so it's loosely packed until the sausage is plump but not tight, which stops it bursting on the grill. Tie the end."},{"text":"Heat your barbecue or grill plate to medium-high until hot and sizzling when a little oil hits it, and oil the grates."},{"text":"Coil the sausage onto the hot grill. Cook for 12 minutes, turning every couple of minutes to colour all sides evenly. The casing should be dark brown and crackling, and the meat cooked through when you press it."},{"text":"Transfer to a plate and let it rest for a minute. Serve with sticky rice, lime wedges and fresh coriander and chilli on the side."}],"id":"54b403a5-a55c-4609-93d2-ee7ab4f63f18"},{"steps":[{"text":"Bring a large pot of salted water to a boil. Add the greens in batches if needed, stirring so they wilt evenly."},{"text":"Simmer until the greens are completely tender, about 10–15 minutes. The water should taste like the sea."},{"text":"Drain in a colander, gently pressing out excess water with the back of a spoon, don't squeeze them dry."},{"text":"Divide the warm greens among plates. Drizzle each serving generously with olive oil, then squeeze lemon juice over the top. Season with salt to taste and serve warm or at room temperature."}],"id":"9512b52b-111f-4b0c-a8cd-3757cc951cdd"},{"notes":["Make it the day before, it thickens as it sits and tastes even better reheated. Add a splash of stock when you warm it up.","Use any crusty bread: sourdough, ciabatta, or even that discounted loaf from the Central Market."],"id":"c24b4848-2d14-4d96-a6eb-6f0f24ef091a"},{"notes":["Make the kebab mixture up to 2 hours ahead and chill until ready to cook.","If you don't have metal skewers, use wooden ones soaked in cold water for 30 minutes.","A cast iron pan works brilliantly for the high heat and even browning.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"8d03a9f0-a4c9-462d-a30f-f5a64fdb951e"},{"notes":["Make the sambal paste up to a day ahead and store in a jar in the fridge, it keeps well and the flavours deepen.","For extra richness, use coconut oil instead of neutral oil for the sambal.","If you prefer it milder, use fewer dried chillies or remove more seeds; if you like serious heat, add an extra fresh chilli."],"id":"fa4846c5-6ab8-4002-aa67-f09408cb8110"},{"notes":["Haleem improves overnight: make it the day before, cool and store in the fridge, then gently reheat and add fresh crispy onions and ginger before serving.","If using a slow cooker, use the same ingredients and cook on low for 8 hours, stirring halfway through. The texture will be slightly looser, add a little less stock if using this method.","For a leaner dish, use lamb shoulder or goat instead of beef; cooking time stays the same.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat 3 tbsp ghee in a large heavy-based pot over medium heat. Working in batches, brown the beef on all sides, 8–10 minutes total. Set aside."},{"text":"In the same pot, add the diced onion and cook, stirring, until soft and golden, about 5 minutes. Add the garlic and ginger, cook for 1 minute until fragrant."},{"text":"Add cumin, coriander, garam masala, turmeric and cayenne. Stir constantly for 1 minute to bloom the spices."},{"text":"Return the beef to the pot. Add the crushed tomatoes and stir well. Cook for 2 minutes."},{"text":"Add the brown lentils, split chickpeas, stock and salt. Stir to combine. Bring to a boil, then reduce heat to low, cover with a lid slightly ajar, and simmer gently for 2½ to 3 hours, stirring occasionally to prevent sticking. The meat should fall apart, the lentils dissolve, and the mixture thicken into a porridge-like consistency. If it's too thick, add more water; if too thin, simmer uncovered toward the end."},{"text":"Taste and adjust salt and spice. The haleem should be creamy and almost paste-like, with no visible lentil pieces, break up any remaining chunks with a wooden spoon."},{"text":"About 15 minutes before serving, prepare the garnish. Heat 2 tbsp ghee in a small pan over medium heat. Add the sliced onion and cook, stirring often, until deep golden and crispy, about 8–10 minutes. Add the ginger matchsticks and cook for 1 minute."},{"text":"Spoon the haleem into bowls, top generously with the crispy onions and ginger, scatter with fresh coriander if using, and serve with lemon wedges on the side. Pour any remaining ghee and pan juices over the top."}],"id":"0b232b0e-6632-4911-ac21-f7dc1fa928c9"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;